export function getMoveFX(moveName) {
  const row = MOVE_FX[moveName];
  if (row) {
    return {
      type: row[0],
      category: row[1] === "P" ? "Physical" : row[1] === "S" ? "Special" : "Status",
      style: row[2],
    };
  }
  return {type: "Normal", category: "Physical", style: "strike"};
}
